SELECT COUNT(*)
FROM member_config
WHERE deleted = 0 AND status = '生效'
AND create_time >= #{start}
AND create_time <= #{end}

SELECT ROUND( IFNULL( SUM(CASE WHEN status = '生效' THEN 1 ELSE 0 END) / NULLIF(SUM(CASE WHEN status IN ('生效', '禁用') THEN 1 ELSE 0 END), 0) , 0), 2 ) AS passRate FROM member_config WHERE deleted = 0
AND create_time >= #{start}
AND create_time <= #{end}
